internal class UPSPricingRuleBuilder_PriceTermJournalTrans extends UPSPricingRuleBuilder
{
    private UPSPriceTermJournalTable journalTable;

}

Method.Source:
public static void main(Args args)
{
    UPSPricingRuleBuilder_PriceTermJournalTrans createRule;
    createRule = new UPSPricingRuleBuilder_PriceTermJournalTrans(args.record());

    createRule.createRecord();
}

public void initMasterRecord()
{
    UPSPriceTermJournalTrans journalTrans;

    journalTrans.clear();
    journalTrans.AgreementId = this.journalTable.AgreementId;
    journalTrans.initfromUPSPriceTermJournalTable(this.journalTable);
    journalTrans.LineNum = UPSPriceTermJournalTrans::lastLineNum(journalTable.AgreementId) + SystemParameters::getSystemLineNumberIncrement();

    this.masterRecord = journalTrans;
}

public void linkPricingRule(UPSPricingRule _pricingRule)
{
    if (this.dialogOk && _pricingRule)
    {
        UPSPriceTermJournalTrans createdJournalTrans = masterRecord;

        createdJournalTrans.PricingRule = _pricingRule.RecId;
    }
}
